let lookback = 90d;
// IdentityInfo is the account inventory; users absent from SigninLogs in the window are dormant.
// SigninLogs retention must cover the full lookback.
let activeUsers = SigninLogs
    | where TimeGenerated > ago(lookback)
    | distinct UPN = tolower(UserPrincipalName);
IdentityInfo
| where TimeGenerated > ago(14d)
| summarize arg_max(TimeGenerated, *) by AccountUPN
| where IsAccountEnabled == true
| extend UPN = tolower(AccountUPN)
| join kind=leftanti activeUsers on UPN
| project AccountUPN, AccountDisplayName, Department, AccountCreationTime
